const readLines = (source: string) => source.split("\n").map((line) => line.trim()).filter(Boolean);

export function getTruthSourceLines(): string[] {
  return readLines(TRUTH_SOURCE);
}

export function getDareSourceLines(): string[] {
  return readLines(DARE_SOURCE);
}
